{
  "name": "@loreai/opencode",
  "version": "0.40.0",
  "type": "module",
  "license": "FSL-1.1-Apache-2.0",
  "description": "Three-tier memory architecture for OpenCode — distillation, not summarization",
  "main": "./src/index.ts",
  "types": "./src/index.ts",
  "exports": {
    ".": {
      "types": "./src/index.ts",
      "bun": "./src/index.ts",
      "default": "./src/index.ts"
    }
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.1.0"
  },
  "dependencies": {
    "@loreai/core": "0.40.0",
    "@loreai/gateway": "0.40.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.1.39",
    "@opencode-ai/sdk": "^1.1.39",
    "@types/bun": "^1.2.0"
  },
  "files": [
    "src/",
    "README.md",
    "LICENSE"
  ],
  "repository": {
    "type": "git",
    "url": "git+https://github.com/BYK/loreai.git",
    "directory": "packages/opencode"
  },
  "publishConfig": {
    "access": "public"
  },
  "keywords": [
    "opencode",
    "plugin",
    "memory",
    "agent",
    "distillation",
    "llm"
  ],
  "author": "BYK",
  "scripts": {
    "typecheck": "tsc --noEmit",
    "build": "echo '@loreai/opencode ships raw TS — no build step needed'"
  }
